cd /tmp && python3 - <<'EOF'
import pandas as pd, json

t = pd.read_html('gdp_20250601035541.html')[0]
t.columns = [c.strip() for c in t.columns]
def pshare(s):
    try: return float(str(s).replace('%','').replace('−','-').strip())
    except: return None
t['share'] = t['Share of World GDP'].map(pshare)
cand = t[t['share']>=0.1]

name2iso = {
 'United States':'USA','China':'CHN','Germany':'DEU','Japan':'JPN','India':'IND','United Kingdom':'GBR','France':'FRA','Italy':'ITA','Brazil':'BRA','Canada':'CAN','Russia':'RUS','Mexico':'MEX','Australia':'AUS','South Korea':'KOR','Spain':'ESP','Indonesia':'IDN','Netherlands':'NLD','Turkey':'TUR','Saudi Arabia':'SAU','Switzerland':'CHE','Poland':'POL','Argentina':'ARG','Belgium':'BEL','Sweden':'SWE','Ireland':'IRL','Thailand':'THA','United Arab Emirates':'ARE','Israel':'ISR','Austria':'AUT','Singapore':'SGP','Norway':'NOR','Bangladesh':'BGD','Philippines':'PHL','Vietnam':'VNM','Denmark':'DNK','Iran':'IRN','Malaysia':'MYS','Egypt':'EGY','Hong Kong':'HKG','South Africa':'ZAF','Nigeria':'NGA','Colombia':'COL','Romania':'ROU','Czech Republic (Czechia)':'CZE','Pakistan':'PAK','Chile':'CHL','Finland':'FIN','Portugal':'PRT','Peru':'PER','Kazakhstan':'KAZ','New Zealand':'NZL','Iraq':'IRQ','Algeria':'DZA','Greece':'GRC','Qatar':'QAT','Hungary':'HUN','Ukraine':'UKR','Kuwait':'KWT','Ethiopia':'ETH','Morocco':'MAR','Slovakia':'SVK','Dominican Republic':'DOM','Ecuador':'ECU','Sudan':'SDN','Oman':'OMN','Kenya':'KEN',
}

data = json.load(open('wb_growth.json'))
rows = data[1]
g = {}
for r in rows:
    iso = r['countryiso3code']; yr = int(r['date']); v = r['value']
    if v is None: continue
    g.setdefault(iso, {})[yr] = v

results = []
missing = []
for _, row in cand.iterrows():
    c = row['Country']; iso = name2iso.get(c)
    if not iso or iso not in g:
        missing.append((c, iso)); continue
    series = g[iso]
    yrs = list(range(2012,2021))
    vals = {y: series.get(y) for y in yrs}
    if any(v is None for v in vals.values()):
        missing.append((c, vals)); continue
    ok = all(v > 1.5 for v in vals.values())
    results.append((c, iso, ok, vals))

print("MISSING:", missing)
print()
for c, iso, ok, vals in results:
    if ok:
        print("PASS", c, {y: round(v,2) for y,v in vals.items()})
print()
print("Near-misses / failures (min value >0 but <=1.5):")
for c, iso, ok, vals in results:
    if not ok:
        mn = min(vals.values())
        print("FAIL", c, {y: round(v,2) for y,v in vals.items()})
EOF

